content.code_snippet:
class Spacecraft {
  constructor(name, fuel) {
    this.name = name;
    this.fuel = fuel;
  }

  launch() {
    const launchInfo = [];
    launchInfo.push(this.name);
    launchInfo.push("is launching with");
    launchInfo.push(this.fuel);
    launchInfo.push("units of fuel!");
    // Using an unnecessary array and join operation for a simple string interpolation
    return launchInfo.join(" ");
  }
}

class ExplorerShip extends Spacecraft { 
  constructor(name, fuel, scannerType) {
    super(name, fuel);
    // Explicitly re-assigning name and fuel after super() is redundant, as super() already initializes them.
    this.name = name;
    this.fuel = fuel;
    this.scannerType = scannerType;
  }

  scanPlanets() {
    let scanDetail = "";
    // Building the string with multiple concatenations is less readable and slightly less efficient
    // for simple strings compared to using a single template literal.
    scanDetail += this.name;
    scanDetail += " is scanning planets with its ";
    scanDetail += this.scannerType;
    scanDetail += " scanner!";
    return scanDetail;
  }
}

